                        UPDATE loan_record
                        SET status = ?, seal_passed = ?, return_note = ?, returned_at = ?
                        WHERE id = ? AND status = ?
                        """,
                LoanStatus.RETURNED.name(), sealPassed ? 1 : 0, note, returnedAt,
