package com.example.starter.evidence;

/**
 * 检验预约状态（只进不退的状态机）。
 * SCHEDULED 已预约未开始（占用检验台容量与证物时段，可取消）；
 * IN_PROGRESS 检验中（证物为 EXAMINATION，不可取消）；
 * COMPLETED 已完成（不可再变）；CANCELLED 未开始即取消（不可再变，释放台位）。
 */
public enum ReservationStatus {
    SCHEDULED,
    IN_PROGRESS,
    COMPLETED,
    CANCELLED
}

package com.example.starter.evidence;

/**
 * 检验保管链事件类型，只追加、不可变。
 * RESERVED 创建预约；STARTED 开始检验（证物离开库房的临时链记录）；
 * COMPLETED 完成检验（含结果摘要与新封签版本）；CANCELLED 取消未开始预约。
 */
public enum ExaminationEventType {
    RESERVED,
    STARTED,
    COMPLETED,
    CANCELLED
}

