        .orElseThrow(() -> ApiException.notFound("检验台不存在: " + benchKey));
List<ReservationPlanner.Interval> intervals =
        reservationRepository.findByBenchInWindow(benchKey, from, to).stream()
                .map(r -> new ReservationPlanner.Interval(r.startAt(), r.endAt()))
                .toList();
List<LoadSegmentView> segments = ReservationPlanner.segments(intervals).stream()
        .map(segment -> ReservationPlanner.clip(
                new ReservationPlanner.Interval(segment.start(), segment.end()), from, to))
        .flatMap(Optional::stream)
        .map(clip -> {
            List<ReservationPlanner.Interval> inClip = intervals.stream()
                    .map(i -> ReservationPlanner.clip(i, clip.start(), clip.end()))
                    .flatMap(Optional::stream)
                    .toList();
            int load = ReservationPlanner.peakLoad(inClip);
            int remaining = bench.capacity() - load;
            // 利用率比例以千分位整数返回（load/capacity），避免浮点序列化不稳定。
            int utilizationPermille = Math.round(load * 1000f / bench.capacity());
            return new LoadSegmentView(clip.start(), clip.end(), load, bench.capacity(),
                    remaining, utilizationPermille);
        })
        .sorted(Comparator.comparing(LoadSegmentView::start)
                .thenComparing(LoadSegmentView::end))
        .toList();
return new BenchDiagnosticsView(toView(bench), from, to, segments);

