        body.put("reservationKey", reservationKey);
        body.put("benchKey", benchKey);
        body.put("examinerId", examiner);
        body.put("startAt", start);
        body.put("endAt", end);
        return body;
    }

    private MvcResult reserve(String actor, String evidenceKey, String reservationKey,
                              String benchKey, String examiner,
                              LocalDateTime start, LocalDateTime end) throws Exception {
        return postJson("/api/evidence/{key}/examination-reservations", "x", evidenceKey)
                .getResponse() == null ? null : performReserve(actor, evidenceKey,
                reserveBody(reservationKey, benchKey, examiner, start, end));
