        assertThat(failed.getResponse().getStatus()).isEqualTo(409);
        assertThat(objectMapper.readTree(failed.getResponse().getContentAsString())
                .get("message").asText()).contains("差额=1");

        // 整批失败不留半成品：ev2、ev4 均无预约与事件，闲台位仍可用
